const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kabulPoint = ee.Geometry.Point([69.2075, 34.5553]);
  const areaOfInterest = kabulPoint.buffer(48280); // 30 miles in meters
  const startDate2017 = '2017-02-01';
  const endDate2017 = '2017-03-01';
  const startDate2018 = '2018-02-01';
  const endDate2018 = '2018-03-01';

  // 2. Data Acquisition
  const dataset = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
                  .select('SWE_inst');

  const collection2017 = dataset.filterDate(startDate2017, endDate2017).filterBounds(areaOfInterest);
  const collection2018 = dataset.filterDate(startDate2018, endDate2018).filterBounds(areaOfInterest);

  // 3. Data Availability Check
  const size2017 = collection2017.size().getInfo();
  const size2018 = collection2018.size().getInfo();

  if (size2017 === 0 || size2018 === 0) {
    console.log(`Image count 2017: ${size2017}`);
    console.log(`Image count 2018: ${size2018}`);
    console.log('C1: Empty Collection');
    return;
  }
  console.log(`Image count 2017: ${size2017}`);
  console.log(`Image count 2018: ${size2018}`);

  // 4. Processing and Calculation
  const mean2017 = collection2017.mean();
  const mean2018 = collection2018.mean();

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2017 = mean2017.reduceRegion({
    reducer: reducer,
    geometry: areaOfInterest,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2018 = mean2018.reduceRegion({
    reducer: reducer,
    geometry: areaOfInterest,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const swe2017 = stats2017['SWE_inst_mean'];
  const count2017 = stats2017['SWE_inst_count'];
  const swe2018 = stats2018['SWE_inst_mean'];
  const count2018 = stats2018['SWE_inst_count'];

  // 5. Validation & Final Answer
  if (count2017 === 0 || count2018 === 0) {
    console.log(`Valid pixels 2017: ${count2017}`);
    console.log(`Valid pixels 2018: ${count2018}`);
    console.log('C2: No Valid Pixels');
    return;
  }
  console.log(`Feb 2017 Mean SWE (kg/m^2): ${swe2017.toFixed(2)}, Pixels: ${count2017}`);
  console.log(`Feb 2018 Mean SWE (kg/m^2): ${swe2018.toFixed(2)}, Pixels: ${count2018}`);

  if (swe2017 === null || swe2018 === null || isNaN(swe2017) || isNaN(swe2018)) {
    console.log('C3: Calculation Failure');
    return;
  }

  if (swe2018 > swe2017) {
    console.log('A');
  } else {
    console.log('B');
  }
}

